import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import App from './App'
import { RootErrorBoundary } from './components/ErrorBoundary'
// Hint/tooltip surfaces. Imported here (not from index.html) so the stylesheet travels with the
// bundle in dev and in the production build — web/frontend/index.html is regenerated by the
// build step and must not be hand-edited.
import './hints/hints.css'

const root = document.getElementById('root')
if (!root) {
  throw new Error('Root element #root not found in index.html')
}

// Neutral browser tab title in stock builds. The
// static <title> in web/frontend/index.html is copied verbatim by vite's
// publicDir step (outDir == publicDir, so any build-time HTML rewrite loses to
// the copy) — rewrite it here, before first paint, from the same compile-time
// constant. Stock: 'XMage — Web Client'; LLMage keeps the static default.
if (!__LLMAGE__) {
  document.title = 'XMage — Web Client'
}

// The error boundary lives OUTSIDE App (app root, this file): a render throw
// anywhere inside <App /> must be caught by a boundary that is itself not part
// of the crashing tree. Root-only by design — no per-subtree catch-alls.
createRoot(root).render(
  <StrictMode>
    <RootErrorBoundary>
      <App />
    </RootErrorBoundary>
  </StrictMode>
)